class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        m = 33554431
        n = len(nums)
        i = 0
        s = 33554431
        c = 0

        if m == 0:
            i = 0
            while i < n:
                s = s & nums[i]
                if i == n - 1:
                    if s != m:
                        return c
                    else:
                        s = 33554431
                        c += 1
                        i = 0
                else:
                    if s == m:
                        s = 33554431
                        c += 1
                        i = 0
                    else:
                        i += 1
        else:
            i = 0
